    """기존 기록의 장비 칸(또는 연결된 고객 장비)을 장비 목록의 첫 줄로 옮긴다."""
    ServiceCase = apps.get_model('reporting', 'ServiceCase')
    ServiceEquipment = apps.get_model('reporting', 'ServiceEquipment')
    rows = []
    for case in ServiceCase.objects.select_related('asset').iterator():
        asset = case.asset
        name = case.equipment_name or (asset.asset_name if asset else '')
        model_name = case.model_name or (asset.model_name if asset else '')
        serial = case.serial_number or (asset.serial_number if asset else '')
        if name or model_name or serial:
            rows.append(ServiceEquipment(
                case_id=case.id, name=name[:200], model_name=model_name[:200], serial_number=serial[:120], position=0,
            ))
    ServiceEquipment.objects.bulk_create(rows, batch_size=500)


